import React, { useState, useEffect } from 'react';
import MapDisplay from './MapDisplay';
import './App.css';

function App() {
  // State for daily customer count.
  const [dailyCustomerCount, setDailyCustomerCount] = useState(0);

  // Customer-related state.
  const [customers, setCustomers] = useState([]);
  const [selectedCustomerIds, setSelectedCustomerIds] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");

  // Storage-related state.
  const [storages, setStorages] = useState([]);
  const [selectedStorageId, setSelectedStorageId] = useState(null);
  const [storageSearchTerm, setStorageSearchTerm] = useState("");

  // Truck & product details.
  const [numTrucks, setNumTrucks] = useState(0);
  const [productWeight, setProductWeight] = useState(0);

  // Optimization result.
  const [optimizationResult, setOptimizationResult] = useState(null);

  // Fetch customers
  useEffect(() => {
    fetch("http://127.0.0.1:5000/customers")
      .then(res => res.json())
      .then(data => {
        const norm = data.customers.map(c => ({
          id:       c.CustomerID,
          name:     c.CustomerName,
          address:  c.CustomerAddress,
          location: [c.CustomerLat, c.CustomerLong],
        }));
        setCustomers(norm);
      })
      .catch(err => console.error("Error fetching customers:", err));
  }, []);

  // Fetch storages
  useEffect(() => {
    fetch("http://127.0.0.1:5000/storages")
      .then(res => res.json())
      .then(data => {
        const norm = data.storages.map(s => ({
          id:       s.StorageID,
          name:     s.StorageName,
          address:  s.StorageAddress,
          location: [s.StorageLat, s.StorageLong],
        }));
        setStorages(norm);
        if (norm.length) setSelectedStorageId(norm[0].id);
      })
      .catch(err => console.error("Error fetching storages:", err));
  }, []);

  // Filtered lists
  const filteredCustomers = customers.filter(
    ({ name, address }) =>
      name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      address.toLowerCase().includes(searchTerm.toLowerCase())
  );
  const filteredStorages = storages.filter(
    ({ name, address }) =>
      name.toLowerCase().includes(storageSearchTerm.toLowerCase()) ||
      address.toLowerCase().includes(storageSearchTerm.toLowerCase())
  );

  // Toggle customer selection (multi-select)
  const handleCustomerToggle = id => {
    setSelectedCustomerIds(prev =>
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  // Submit to /optimize
  const handleSubmit = async () => {
    const stops   = customers
      .filter(c => selectedCustomerIds.includes(c.id))
      .map(c => c.location);
    const depotLoc = storages.find(s => s.id === selectedStorageId)?.location || null;

    const payload = {
      locations:       stops,
      num_vehicles:    numTrucks,
      depot:           depotLoc,
      storage_address: storages.find(s => s.id === selectedStorageId)?.address || "",
      daily_customers: dailyCustomerCount,
      total_weight:    productWeight,
    };

    try {
      const res    = await fetch("http://127.0.0.1:5000/optimize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const result = await res.json();
      setOptimizationResult(result);
    } catch (e) {
      console.error("Error optimizing routes:", e);
    }
  };

  // Map data
  const routeData    = optimizationResult?.routes?.[0]?.route || [];
  const defaultCenter = storages.find(s => s.id === selectedStorageId)?.location || [0, 0];

  return (
    <div className="container">
      <header className="header">
        <div className="header-left">
          <h1 className="route-name">Delivery Optimizer</h1>
          <p className="route-desc">Your daily route optimization solution</p>
        </div>
        <div className="header-right">
          <button className="btn new-route">+ Create new route</button>
        </div>
      </header>

      <div className="content">
        <aside className="sidebar">
          {/* Customers */}
          <div className="stops-section">
            <h3>Customers</h3>
            <input
              type="text"
              className="search-input"
              placeholder="Search customers..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
            <div className="customer-list">
              {filteredCustomers.map(c => (
                <div
                  key={c.id}
                  onClick={() => handleCustomerToggle(c.id)}
                  className={`customer-item ${
                    selectedCustomerIds.includes(c.id) ? "selected" : ""
                  }`}
                >
                  <strong>{c.name}</strong>
                  <p>{c.address}</p>
                </div>
              ))}
              {filteredCustomers.length === 0 && <p>No customers found.</p>}
            </div>
          </div>

          {/* Storages */}
          <div className="stops-section">
            <h3>Storages</h3>
            <input
              type="text"
              className="search-input"
              placeholder="Search storages..."
              value={storageSearchTerm}
              onChange={e => setStorageSearchTerm(e.target.value)}
            />
            <div className="customer-list">
              {filteredStorages.map(s => (
                <div
                  key={s.id}
                  onClick={() => setSelectedStorageId(s.id)}
                  className={`customer-item ${
                    selectedStorageId === s.id ? "selected" : ""
                  }`}
                >
                  <strong>{s.name}</strong>
                  <p>{s.address}</p>
                </div>
              ))}
              {filteredStorages.length === 0 && <p>No storages found.</p>}
            </div>
          </div>
        </aside>

        <main className="main-area">
          <div className="form-section">
            <div className="input-group">
              <label>Daily Customer Count:</label>
              <input
                type="number"
                min="0"
                value={dailyCustomerCount}
                onChange={e => setDailyCustomerCount(Number(e.target.value))}
                className="number-input"
              />
            </div>
            <div className="input-group">
              <label>Trucks Needed:</label>
              <input
                type="number"
                min="0"
                value={numTrucks}
                onChange={e => setNumTrucks(Number(e.target.value))}
                className="number-input"
              />
            </div>
            <div className="input-group">
              <label>Product Weight (kg):</label>
              <input
                type="number"
                min="0"
                value={productWeight}
                onChange={e => setProductWeight(Number(e.target.value))}
                className="number-input"
              />
            </div>
            <button onClick={handleSubmit} className="btn optimize-btn">
              Submit for Optimized Route
            </button>
          </div>

          <div className="map-container">
            <MapDisplay
              routeData={routeData}
              defaultCenter={defaultCenter}
              zoom={13}
            />
          </div>
        </main>
      </div>

      {optimizationResult && (
        <div className="result-container">
          <h2>Optimization Result</h2>
          <pre className="result-output">
            {JSON.stringify(optimizationResult, null, 2)}
          </pre>
        </div>
      )}
    </div>
  );
}

export default App;
